Account.ready.then(async user=>{
 const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const admin=user.role==='admin';let exams=[],bank=[],selected=new Set(),pending=null,busy=false,seq=0;
 $('admin-tools').hidden=!admin;document.querySelectorAll('.admin-count').forEach(e=>e.hidden=!admin);$('home-link').href=admin?'/admin-home.html':'/sets.html';$('exam-help').textContent=admin?'Activate one exam per topic. Deactivating removes it from current rankings; attempts and results remain saved. Changing the active exams changes eligibility and aggregate rankings.':user.role==='learner'?'Only these designated exams count toward rankings. Unfinished attempts do not count.':'Editor accounts can view rankings. Only learners can take ranked exams.';
 function options(el,values,empty){const old=el.value;el.replaceChildren(...(empty?[new Option(empty,'')]:[]),...values.map(x=>new Option(x,x)));if(values.includes(old))el.value=old;}
 const shown=()=>bank.filter(q=>q.subject===$('pick-subject').value&&q.topic===$('pick-topic').value&&(q.display_code+' '+q.text+' '+(q.case_id||'')).toLowerCase().includes($('pick-search').value.toLowerCase()));
 function select(q,on){for(const x of bank.filter(x=>q.case_id?x.case_id===q.case_id:x.id===q.id))on?selected.add(x.id):selected.delete(x.id);}
 function picker(){const qs=shown();$('question-picker').innerHTML=qs.map(q=>`<label class="pick-row"><input type="checkbox" data-id="${esc(q.id)}" ${selected.has(q.id)?'checked':''}><span><strong>${esc(q.display_code)}</strong> ${esc(q.text)}<small>${q.maximum} points${q.case_id?' · Full case '+esc(q.case_id):' · Standalone'}</small></span></label>`).join('')||'<p>No published questions in this topic.</p>';$('question-picker').querySelectorAll('input').forEach(b=>b.onchange=()=>{select(bank.find(q=>q.id===b.dataset.id),b.checked);picker()});const chosen=bank.filter(q=>selected.has(q.id));$('pick-count').textContent=chosen.length+' selected · '+chosen.reduce((n,q)=>n+q.maximum,0)+' points';$('create-exam').disabled=!chosen.length;}
 function pickerTopics(){options($('pick-topic'),[...new Set(bank.filter(q=>q.subject===$('pick-subject').value).map(q=>q.topic))].sort());selected.clear();picker()}
 function confirmation(title,html,action){pending=action;$('confirm-heading').textContent=title;$('confirm-body').innerHTML=html;$('confirm-error').textContent='';$('rank-confirm').showModal()}
 $('rank-cancel').onclick=()=>{if(!busy)$('rank-confirm').close()};$('rank-confirm').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('rank-confirm-button').onclick=async()=>{if(busy||!pending)return;busy=true;$('rank-confirm-button').disabled=$('rank-cancel').disabled=true;try{await pending();$('rank-confirm').close();await load();}catch(e){$('confirm-error').textContent=e.message}finally{busy=false;$('rank-confirm-button').disabled=$('rank-cancel').disabled=false}};
 $('pick-subject').onchange=pickerTopics;$('pick-topic').onchange=()=>{selected.clear();picker()};$('pick-search').oninput=picker;$('pick-all').onclick=()=>{shown().forEach(q=>select(q,true));picker()};$('pick-clear').onclick=()=>{selected.clear();picker()};$('create-exam').onclick=()=>{const title=$('exam-title').value.trim();if(!title){$('rank-message').textContent='Enter an exam title.';return}const ids=[...selected],qs=bank.filter(q=>selected.has(q.id));confirmation('Create fixed ranked exam?',`<p>${esc(title)} · ${qs.length} questions. It will be created inactive. A verified backup is required.</p><ul>${qs.map(q=>`<li>${esc(q.display_code)} · ${esc(q.text)} · ${q.maximum} points</li>`).join('')}</ul>`,async()=>{await Account.request('/api/admin/ranked-exams',{action:'create',title,question_ids:ids});selected.clear();picker();$('rank-message').textContent='Ranked exam created. Activate it when ready.'})};
 async function load(){exams=await Account.request(admin?'/api/admin/ranked-exams':'/api/ranked-exams');$('exam-list').innerHTML=exams.map(e=>`<div class="exam-row"><div><h3>${esc(e.title)} <span class="pill ${e.active?'':'inactive'}">${e.active?'Active':'Inactive'}</span></h3><p>${esc(e.subject)} / ${esc(e.topic)} · ${e.questions} questions · ${e.maximum} points</p></div>${admin?`<button class="secondary" data-toggle="${esc(e.id)}">${e.active?'Deactivate':'Activate'}</button>`:user.role==='learner'?`<button class="primary" data-start="${esc(e.id)}">Take exam</button>`:''}</div>`).join('')||'<p>No ranked exams are available yet.</p>';
 document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const e=exams.find(x=>x.id===b.dataset.toggle);confirmation((e.active?'Deactivate':'Activate')+' ranked exam?',`<p>${esc(e.title)}</p><p>This changes the exams required for topic, subject and overall rankings. Saved results remain unchanged. Attempt counts are specific to this fixed exam.</p>`,()=>Account.request('/api/admin/ranked-exams',{action:e.active?'deactivate':'activate',id:e.id}))});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const a=await Account.request('/api/ranked-exams/start',{exam_id:b.dataset.start});location.href='/?set=1&attempt='+encodeURIComponent(a.id)}catch(e){$('rank-message').textContent=e.message;b.disabled=false}});
 options($('rank-subject'),[...new Set(exams.filter(e=>e.active).map(e=>e.subject))].sort());rankTopics();await board();}
 function rankTopics(){options($('rank-topic'),[...new Set(exams.filter(e=>e.active&&e.subject===$('rank-subject').value).map(e=>e.topic))].sort())}
 async function board(){const request=++seq,scope=$('rank-scope').value;$('rank-subject').disabled=scope==='overall';$('rank-topic').disabled=scope!=='topic';$('rank-history').replaceChildren();try{const r=await Account.request('/api/rankings?'+new URLSearchParams({scope,subject:$('rank-subject').value,topic:$('rank-topic').value}));if(request!==seq)return;const me=r.ineligible.find(x=>x.is_you);$('eligibility').textContent=!r.required_exams?'No active ranked exams for this selection.':me?'Not yet eligible: '+me.completed_exams+' of '+me.required_exams+' required exams completed.':r.required_exams+' required exam(s).';$('rank-rows').innerHTML=r.rows.map((x,i)=>`<tr class="${x.is_you?'you':''}"><td>${x.rank}</td><td>${esc(x.name)}${x.is_you?' (you)':''}</td><td>${x.score.toFixed(2)}%</td>${admin?`<td>${x.attempts}</td><td><button class="secondary" data-history="${i}">View history</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${admin?5:3}">No eligible learners yet.</td></tr>`;document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const x=r.rows[Number(b.dataset.history)];$('rank-history').innerHTML=`<h3>${esc(x.name)} · Ranked attempt history</h3>`+x.history.map(a=>`<p>${esc(exams.find(e=>e.id===a.exam_id)?.title||a.exam_id)} · ${a.score.toFixed(2)}% · ${esc(new Date(a.submitted).toLocaleString())}</p>`).join('')});}catch(e){if(request===seq)$('eligibility').textContent=e.message}}
 $('rank-scope').onchange=board;$('rank-subject').onchange=()=>{rankTopics();board()};$('rank-topic').onchange=board;
 try{if(admin){bank=(await Account.request('/api/questions')).filter(q=>q.status==='Published');options($('pick-subject'),[...new Set(bank.map(q=>q.subject))].sort());pickerTopics()}await load()}catch(e){$('rank-message').textContent=e.message}
});
